import { withBase } from "@/utils/assets"

// Every model on the island is original, generated by blender/island in this repository (see
// blender/DESIGN.md) and exported as a draco GLB; blender/island/build/stats.json records each
// file's size in metres and its triangle count.
export function islandModel(asset: string) {
  return withBase(`/models/island/${asset}.glb`)
}

/** A texture atlas blender/island renders for one family of models, published beside the models. */
export function islandAtlas(atlas: string) {
  return withBase(`/models/island/${atlas}.png`)
}

