/** A model's base build followed by its character variants: the same design built with other seeds. */
function withVariants(asset: string, suffixes: readonly string[]) {
  return [islandModel(asset), ...suffixes.map((suffix) => islandModel(`${asset}_${suffix}`))]
}

/**
 * Character variants by base model path. A variant changes the lean, stud rhythm, plaster tone and
 * wear, so repeated buildings cycle through them instead of standing as identical copies. The `_b`
 * files of moss_rocks, grass_medium_02, dandelion and gazania are second forms, not variants.
 */
export const MODEL_VARIANTS: ReadonlyMap<string, readonly string[]> = new Map(
  [
    withVariants("house_01", ["b", "c"]),
    withVariants("house_02", ["b", "c"]),
    withVariants("house_03", ["b", "c"]),
    withVariants("market_stand_02", ["b"])
  ].map((paths) => [paths[0], paths])
)

/**
 * The shore build of each tree by base model path: the same tree bent by the sea wind (exposure 0.8
 * against 0.2 for the base build), leaning landward with its seaward side on Blender's +y.
 */
export const SHORE_BUILDS: ReadonlyMap<string, string> = new Map(
  ["cypress", "island_tree_01", "island_tree_02", "tree_small", "spruce", "birch"].map((tree) => [
    islandModel(tree),
    islandModel(`${tree}_b`)
  ])
)
